def transform_v2(grid):
    """
    For each row, find "runs" of alternating non-bg values separated by bg.
    For such runs, fill 2 in alternating positions.
    Background seems to be the dominant value, or 0.
    """
    result = [row[:] for row in grid]

    for r in range(len(grid)):
        row = grid[r]
        if not row:
            continue

        # Determine background per row
        counts = {}
        for val in row:
            counts[val] = counts.get(val, 0) + 1
        bg = max(counts, key=counts.get) if counts else 0

        # Find runs of alternating pattern
        i = 0
        while i < len(row) - 1:
            # Check if we're starting an alternating run
            if row[i] != bg and row[i+1] != bg and row[i] == row[i+2] and i+2 < len(row):
                # Found start of alternating pattern: row[i] == row[i+2]
                # Process this run
                # Pattern is: same, diff, same, diff, same... where diff != bg
                j = i + 1
                while j < len(row) - 1:
                    if row[j] == row[j+2]:
                        # Continue the alternating pattern
                        if j > 0:  # Don't fill the first position
                            result[r][j] = 2 if row[j] == row[j-2] else grid[r][j]
                        j += 2
                    else:
                        break
                    j += 1
                i = j + 1
            elif row[i] != bg and i+1 < len(row):
                # Single value or different pattern
                i += 1
            else:
                i += 2

    return result

